import { execFileSync } from 'node:child_process'

const APP_JS_PATTERN = /^packages\/mirror-media-next\/.*\.(?:js|jsx)$/
const IGNORED_PATTERNS = [
  // Generated by `pnpm build:sw`; the reviewed source remains
  // `service-worker/index.js` until its planned Phase 9 TypeScript migration.
  /^packages\/mirror-media-next\/public\/sw\.js$/,
  // This is an explicitly reviewed Node tooling script, not application code.
  // It replaces a hard-to-read package.json shell one-liner for the SW build.
  /^packages\/mirror-media-next\/scripts\/build-sw\.js$/,
]

const args = new Set(process.argv.slice(2))
const isStaged = args.has('--staged')
const baseRef =
  process.env.NO_NEW_JS_BASE_REF ||
  process.env.BASE_REF ||
  process.env.CHANGE_TARGET

function git(args, options = {}) {
  return execFileSync('git', args, {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    ...options,
  }).trim()
}

const repoRoot = git(['rev-parse', '--show-toplevel'])

function getAddedFiles() {
  // Treat renamed JS/JSX paths as new files so moved application files must
  // become .ts/.tsx.
  if (!isStaged && !baseRef) {
    console.error(
      'No base ref was provided for the no-new-JS/JSX branch check.'
    )
    console.error(
      'Set NO_NEW_JS_BASE_REF to the actual target ref (for example, upstream/dev).'
    )
    process.exit(2)
  }

  const args = isStaged
    ? ['diff', '--cached', '--name-status', '--diff-filter=AR']
    : ['diff', '--name-status', '--diff-filter=AR', `${baseRef}...HEAD`]

  let output
  try {
    output = git(args, { cwd: repoRoot })
  } catch (error) {
    const stderr = error?.stderr?.trim()
    console.error(
      `Unable to compare new JS/JSX files${baseRef ? ` against "${baseRef}"` : ''}.`
    )
    if (stderr) {
      console.error(stderr)
    }
    console.error(
      'Fetch the target ref or set NO_NEW_JS_BASE_REF to a ref available in this checkout.'
    )
    process.exit(2)
  }

  return output
    .split('\n')
    .filter(Boolean)
    .map((line) => line.split('\t').at(-1))
    .filter(Boolean)
}

const addedApplicationFiles = getAddedFiles().filter(
  (filePath) =>
    APP_JS_PATTERN.test(filePath) &&
    IGNORED_PATTERNS.every((pattern) => pattern.test(filePath) === false)
)

if (addedApplicationFiles.length > 0) {
  console.error('New application .js or .jsx files are not allowed.')
  console.error('Use .ts or .tsx for new files instead:')
  for (const filePath of addedApplicationFiles) {
    console.error(`- ${filePath}`)
  }
  process.exit(1)
}
